bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
const env=process.env;
const pool=new pg.Pool({
 host:env.VIDEOBOT_DB_HOST,database:env.VIDEOBOT_DB_NAME,user:env.VIDEOBOT_DB_USER,
 password:readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,
 connectionTimeoutMillis:5000});
const egress=createCreatorTelegramFetch(globalThis.fetch);
try {
 const {rows}=await pool.query(
  "SELECT pack_name,file_unique_id,kind FROM videobot_sticker_registration_receipts WHERE phase='needs_reconcile' ORDER BY updated_at DESC LIMIT 1");
 if(rows.length===0){process.exitCode=0;}
 else if(!rows[0].file_unique_id){process.exitCode=80;}
 else {
  const api=createTelegramBotApi({token:readFileSync(env.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim(),
   fetchImpl:egress.fetch,timeoutMs:15000});
  try{
   const set=await api('getStickerSet',{name:rows[0].pack_name});
   const found=Array.isArray(set?.stickers)&&set.stickers.some(s=>s.file_unique_id===rows[0].file_unique_id);
   process.exitCode=found?81:82;
  }catch{process.exitCode=83;}
 }
}catch{process.exitCode=70;}
finally{await egress.close();await pool.end();}
NODE
